window.ACDT_CHARGE("saint-mande",[{"id":"wd-Q778784","cat":"patrimoine","ville":"saint-mande","nom":{"fr":"Place de la Bastille","en":"Place de la Bastille","es":"Plaza de la Bastilla","de":"Place de la Bastille","it":"Place de la Bastille","pt":"Place de la Bastille","nl":"Place de la Bastille","pl":"Plac Bastylii","ru":"Площадь Бастилии","uk":"Площа Бастилії","ar":"ساحة الباستيل","he":"כיכר הבסטיליה","tr":"Bastille Meydanı","el":"Πλατεία της Βαστίλης","sv":"Place de la Bastille","da":"Bastillepladsen","nb":"Place de la Bastille","fi":"Place de la Bastille","cs":"Place de la Bastille","ro":"Place de la Bastille","bg":"Площад на Бастилията","sr":"Трг Бастиље","sl":"Place de la Bastille","ca":"Plaça de la Bastilla","eu":"Bastillako plaza","mk":"Плоштад Бастилја","zh-CN":"巴士底廣場","ja":"バスティーユ広場","ko":"바스티유 광장","fa":"میدان باستی","th":"ปลัสเดอลาบัสตีย์","vi":"Quảng trường Bastille","id":"Place de la Bastille","ms":"Place de la Bastille","ur":"باستیل چوک"},"lat":48.853139,"lon":2.369111,"prix":{"type":"libre"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/PlaceBastille20040914B_commons.jpg/960px-PlaceBastille20040914B_commons.jpg","page":"https://commons.wikimedia.org/wiki/File:PlaceBastille20040914B_commons.jpg","auteur":"Kaihsu","licence":"CC BY-SA 3.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q778784"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Place_de_la_Bastille"},{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/node/704094851"}],"recupere":"2026-11-14","court":{"fr":"place de Paris, en France","en":"square in Paris, France","es":"Plaza de París, Francia","de":"Platz in Paris‎","it":"piazza a Parigi, Francia","pt":"praça de Paris, França","nl":"plein in Parijs, Frankrijk","ru":"площадь в Париже, обязанная своим названием крепости Бастилия, разрушенной во время Великой французской революции","ar":"ساحة في مدينة باريس، فرنسا","he":"כיכר בפריז, צרפת","tr":"Paris'te meydan","el":"πλατεία στο Παρίσι (Γαλλία)","sv":"plats i Paris","fi":"aukio Pariisissa","cs":"náměstí v Paříži","ro":"piață din Paris","sl":"trg v Parizu (Francija)","zh-CN":"法國的廣場","ja":"パリの広場","ur":"پیرس، فرانس میں چوک"},"long":{"pt":"A Praça da Bastilha, em francês Place de la Bastille, é uma praça em Paris, local simbólico da Revolução Francesa, onde a antiga fortaleza da Bastilha foi destruída entre 14 de junho de 1789 e 14 de junho de 1790.","ja":"バスティーユ広場 は、フランスの首都パリにある広場。4区、11区、12区の3つの区に跨っており、広場の周辺地域は単に「バスティーユ」と呼ばれている。もともとはバスティーユ牢獄があった場所であるが、1789年7月14日にフランス革命の発端ともいえるバスティーユ襲撃事件が発生し解体されたため、牢獄は跡形も残っていない。","ar":"ساحة الباستيل (بالفرنسية: Place de la Bastille) ساحة باريسية وهي المكان الرمزي للثورة الفرنسية. وفيها الحصن السابق لسجن الباستيل الذي دمر بين 14 يوليو 1789 وذات اليوم 1790. تعتبر ساحة الباستيل كأحد المعالم السياحية والمواقع الأثرية في باريس وهي قريبة جداً من ساحة فوج التاريخية.","zh-CN":"巴士底广场 是法国首都巴黎的一个广场，是法国大革命的重要纪念地方。","zh-TW":"巴士底廣場 是法國首都巴黎的一個廣場，是法國大革命的重要紀念地方。","ko":"바스티유 광장(프랑스어: Place de la Bastille)은 프랑스 파리에 있는 광장이다. 4구, 11구, 12구에 걸쳐 있으며 광장 주변 지역은 단순히 바스티유라고 불린다. 원래 바스티유 감옥이 있던 곳이지만, 1789년 7월 14일에 프랑스 혁명의 발단이라고도 할 수 있는 바스티유 감옥 습격 사건이 발생하여 해체되었기 때문에 감옥의 흔적은 남아 있지 않다. 현재는 광장 중앙에 1830년에 일어난 7월 혁명을 기념하는 조형물이 세워져 있으며, 주변에는 바스티유 역이나 생마르탱 운하가 있다. 또한 예전에는 국철 바스티유 역도 있었지만 현재는 철거되었고, 부지에 오페라 바스티유라는 극장이 건설되었다.","nl":"De Place de la Bastille is een plein in het centrum van de Franse hoofdstad Parijs. Tot aan de Franse Revolutie stond hier de Bastille Saint-Antoine, die in 1789 werd gesloopt. Bovengronds zijn de contouren van het gebouw met noppen in het plaveisel aangegeven. In het metrostation Bastille is nog een stuk fundering van de vroegere vesting zichtbaar. Gedeeltelijk op dezelfde plaats staat sinds 1989 de Opéra Bastille. Midden op het plein staat sinds 1840 de erezuil Colonne de Juillet.","pl":"Plac Bastylii – plac we wschodniej części Paryża, na prawym brzegu Sekwany.","fr":"La place de la Bastille est une place de Paris, lieu symbolique de la Révolution française, où l'ancienne forteresse de la Bastille fut détruite entre le 14 juillet 1789 et le 14 juillet 1790.","en":"The Place de la Bastille is a square in Paris where the Bastille Prison once stood, until the storming of the Bastille and its subsequent physical destruction between 14 July 1789 and 14 July 1790 during the French Revolution. No vestige of the prison remains, although its footprint is marked by golden discs.","es":"La plaza de Bastilla es una plaza de París, lugar simbólico de la Revolución francesa, situada en el emplazamiento de la antigua fortaleza de la Bastilla, que fue tomada el 14 de julio de 1789.","it":"Place de la Bastille /plas də la basˈtij/ è una piazza di Parigi, luogo simbolo della rivoluzione francese, dove sorgeva l'omonima fortezza assalita il 14 luglio 1789. La piazza si trova a cavallo di 3 arrondissement: il IV, l'XI e il XII. Al centro sorge la Colonne de Juillet, come ricordo della Rivoluzione di luglio del 1830. Inoltre, si trovano qui anche l'Opéra Bastille, la fermata della metropolitana Bastille e il bacino dell'Arsenal, sezione del Canal Saint-Martin. La piazza ospita inoltre concerti e altri eventi culturali; nell'area nord-est si trovano numerosi bar, night club e auditorium.","de":"Die Place de la Bastille in Paris ist heute ein bedeutender städtischer Verkehrsknoten. Es ist gleichzeitig ein symbolischer Ort, denn hier begann die Französische Revolution mit der Erstürmung der Bastille, die dann zwischen dem 14. Juli 1789 und dem 14. Juli 1790 zerstört wurde."},"wiki":{"pt":"https://pt.wikipedia.org/wiki/Pra%C3%A7a_da_Bastilha","ja":"https://ja.wikipedia.org/wiki/%E3%83%90%E3%82%B9%E3%83%86%E3%82%A3%E3%83%BC%E3%83%A6%E5%BA%83%E5%A0%B4","ar":"https://ar.wikipedia.org/wiki/%D8%B3%D8%A7%D8%AD%D8%A9_%D8%A7%D9%84%D8%A8%D8%A7%D8%B3%D8%AA%D9%8A%D9%84","zh-CN":"https://zh.wikipedia.org/wiki/%E5%B7%B4%E5%A3%AB%E5%BA%95%E5%B9%BF%E5%9C%BA","zh-TW":"https://zh.wikipedia.org/wiki/%E5%B7%B4%E5%A3%AB%E5%BA%95%E5%B9%BF%E5%9C%BA","ko":"https://ko.wikipedia.org/wiki/%EB%B0%94%EC%8A%A4%ED%8B%B0%EC%9C%A0_%EA%B4%91%EC%9E%A5","nl":"https://nl.wikipedia.org/wiki/Place_de_la_Bastille","pl":"https://pl.wikipedia.org/wiki/Plac_Bastylii","fr":"https://fr.wikipedia.org/wiki/Place_de_la_Bastille","en":"https://en.wikipedia.org/wiki/Place_de_la_Bastille","es":"https://es.wikipedia.org/wiki/Plaza_de_la_Bastilla","it":"https://it.wikipedia.org/wiki/Place_de_la_Bastille","de":"https://de.wikipedia.org/wiki/Place_de_la_Bastille"}},{"id":"wd-Q269641","cat":"patrimoine","ville":"saint-mande","nom":{"fr":"Colonne de Juillet","en":"July Column","es":"Columna de Julio","de":"Julisäule","it":"Colonna di Luglio","pt":"Coluna de Julho","nl":"Julizuil","ru":"Июльская колонна","uk":"Липнева колона","ar":"عمود يوليو","tr":"Temmuz Sütunu","sv":"Colonne de Juillet","da":"Julisøjlen","nb":"Julisøylen","fi":"Colonne de Juillet","cs":"Červencový sloup","hu":"Július-oszlop","sr":"Јулски стуб","lv":"Jūlija kolonna","ca":"Columna de Juliol","zh-CN":"七月柱","ja":"7月革命記念柱","ko":"7월 기념비","vi":"Cây cột Tháng Bảy"},"lat":48.853056,"lon":2.369167,"prix":{"type":"libre"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Colonne_de_Juillet_972.jpg/960px-Colonne_de_Juillet_972.jpg","page":"https://commons.wikimedia.org/wiki/File:Colonne_de_Juillet_972.jpg","auteur":"Vassil","licence":"Public domain"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q269641"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Colonne_de_Juillet"},{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/way/227757683"}],"recupere":"2026-11-14","court":{"fr":"colonne à Paris","en":"victory column","es":"columna en París","de":"Denkmal auf der Place de la Bastille in Paris","it":"colonna celebrativa a Parigi","nl":"monument in Parijs","cs":"pamětní sloup v Paříži","hu":"emlékoszlop Párizsban"},"long":{"ru":"Июльская колонна — монумент на площади Бастилии в 4-м округе Парижа. Была построена в память о «трёх славных днях» Июльской революции — 27, 28 и 29 июля 1830 года, когда был свергнут король Карл X и на трон взошёл «король-гражданин» Луи-Филипп I.","ja":"7月革命記念柱 は、シャルル10世による復古王政を倒し、オルレアン公ルイ・フィリップによる7月王政をもたらした1830年のフランス7月革命（栄光の三日間）を記念するために、1835年から1840年にかけてパリのバスティーユ広場に建てられた記念碑。","ko":"7월 기념비(七月 紀念碑, 프랑스어: Colonne de Juillet)는 프랑스 파리 바스티유 광장 중심에 있는 기념비이다. 7월 혁명을 기념하기 위해 세워졌다.","zh-CN":"七月柱 是一座位于法国巴黎巴士底广场上的高柱，建于1835年至1840年间，以纪念1830年法国七月革命，该革命曾推翻了查理十世的统治，结束复辟王朝而建立了七月王朝，由路易-菲利普一世继位成为法国国王。","pt":"A Coluna de Julho é uma coluna erguida na Praça da Bastilha em Paris, entre 1835 e 1840, em comemoração aos três dias da Revolução de Julho ocorrida em 1830, conhecida como Os Três Gloriosos, que provocou a queda de Carlos X e do Regime da Restauração e o estabelecimento da Monarquia de Julho, com o reinado de Luís Filipe I, duque de Orleans, que se tornou rei dos franceses.","zh-TW":"七月柱 是一座位於法國巴黎巴士底廣場上的高柱，建於1835年至1840年間，以紀念1830年法國七月革命，該革命曾推翻了查理十世的統治，結束復辟王朝而建立了七月王朝，由路易-菲利普一世繼位成為法國國王。","ar":"عمود يوليو هو عمود نصر يقع في وسط ساحة الباستيل في باريس،فرنسا تم الانتهاء منه في 28 يوليو 1940 في الذكرى العاشرة لثورة يوليو 1830.","es":"La Columna de Julio es un monumento parisino situado en la plaza de la Bastilla en el punto de unión del IV, XI y XII distritos de París. Se construyó para conmemorar la Revolución de 1830.","it":"La colonna di Luglio è un monumento eretto in memoria della rivoluzione di luglio. Essa si trova al centro di Place de la Bastille a Parigi e venne eretta per commemorare le Trois Glorieuses, le \"tre gloriose\" giornate del luglio 1830 che videro la caduta di Carlo X di Francia e l'inizio della \"monarchia di luglio\" di Luigi Filippo.","en":"The July Column is a monumental column in Paris commemorating the Revolution of 1830. It stands in the center of the Place de la Bastille and celebrates the Trois Glorieuses — the 'three glorious' days of 27–29 July 1830 that saw the fall of Charles X, King of France, and the commencement of the July Monarchy of Louis-Philippe, King of the French. It was built between 1835 and 1840.","fr":"La colonne de Juillet est une colonne élevée sur la place de la Bastille à Paris, entre 1835 et 1840 en commémoration des trois journées de la révolution de Juillet survenue en 1830, dite Les Trois Glorieuses, qui amenèrent la chute de Charles X et du régime de la restauration, puis l'instauration de la monarchie de Juillet, avec le règne de Louis-Philippe Ier, duc d'Orléans, devenu roi des Français.","de":"Die Julisäule ist ein Denkmal auf der Place de la Bastille im 11. Arrondissement von Paris."},"wiki":{"ru":"https://ru.wikipedia.org/wiki/%D0%98%D1%8E%D0%BB%D1%8C%D1%81%D0%BA%D0%B0%D1%8F_%D0%BA%D0%BE%D0%BB%D0%BE%D0%BD%D0%BD%D0%B0","ja":"https://ja.wikipedia.org/wiki/7%E6%9C%88%E9%9D%A9%E5%91%BD%E8%A8%98%E5%BF%B5%E6%9F%B1","ko":"https://ko.wikipedia.org/wiki/7%EC%9B%94_%EA%B8%B0%EB%85%90%EB%B9%84","zh-CN":"https://zh.wikipedia.org/wiki/%E4%B8%83%E6%9C%88%E6%9F%B1","pt":"https://pt.wikipedia.org/wiki/Coluna_de_Julho","zh-TW":"https://zh.wikipedia.org/wiki/%E4%B8%83%E6%9C%88%E6%9F%B1","ar":"https://ar.wikipedia.org/wiki/%D8%B9%D9%85%D9%88%D8%AF_%D9%8A%D9%88%D9%84%D9%8A%D9%88","es":"https://es.wikipedia.org/wiki/Columna_de_Julio","it":"https://it.wikipedia.org/wiki/Colonna_di_Luglio","en":"https://en.wikipedia.org/wiki/July_Column","fr":"https://fr.wikipedia.org/wiki/Colonne_de_Juillet","de":"https://de.wikipedia.org/wiki/Julis%C3%A4ule"},"site":"https://www.colonne-de-juillet.fr/","fauteuil":"no"},{"id":"wd-Q1969385","cat":"animaux","ville":"saint-mande","nom":{"fr":"Parc zoologique de Paris","en":"Paris Zoological Park","es":"Zoológico de Vicennes","de":"Parc zoologique de Paris","it":"Parco zoologico di Parigi","pt":"Jardim zoológico de Paris","nl":"Parc Zoologique de Paris","ru":"Венсенский зоопарк","tr":"Paris Zooloji Parkı","nb":"Parc zoologique de Paris","cs":"Zoologická zahrada v Paříži","ca":"Parc zoològic de Vincennes","zh-CN":"巴黎动物园","ja":"パリ動物園","ko":"파리 동물원","fa":"باغ‌وحش پاریس","vi":"Công viên động vật học Paris","id":"Kebun Binatang Paris","ms":"Taman Zoologi Paris","ur":"پیرس چڑیا گھر"},"lat":48.832222,"lon":2.418611,"prix":{"type":"inconnu"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Parc_Zoologique_de_Paris_%28Zoo%29_%40_Paris_%2825743467773%29.jpg/960px-Parc_Zoologique_de_Paris_%28Zoo%29_%40_Paris_%2825743467773%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Parc_Zoologique_de_Paris_(Zoo)_@_Paris_(25743467773).jpg","auteur":"Guilhem Vellut from Paris, France","licence":"CC BY 2.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q1969385"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Parc_zoologique_de_Paris"},{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/way/26008116"},{"nom":"DATAtourisme · Etablissement Public territorial Paris Est Marne et Bois","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/e7dbed81-57a9-3295-b875-194112203ec4"}],"recupere":"2026-11-14","court":{"fr":"parc zoologique français","en":"zoo in France","es":"jardín zoológico en Francia.","de":"Zoo in Frankreich","it":"zoo di Parigi, Francia","nl":"dierentuin in 12e arrondissement van Parijs, Frankrijk","ru":"зоопарк в Париже, Франция","tr":"Fransa'nın Başkenti Paris'te Bulunan Hayvanat Bahçesi","cs":"francouzská zoologická zahrada","ca":"parc zoològic de París","ja":"フランス、パリにある動物園","ko":"파리에 위치한 동물원","vi":"sở thú ở Pháp"},"long":{"pt":"O Jardim zoológico de Paris, também chamado de Zoo de Vincennes, e antigamente conhecido como Jardim Zoológico do Bosque de Vincennes, é um estabelecimento vinculado ao Museu nacional de História Natural da França, situado no arrondissement XII de Paris, cobrindo uma área de 14,5 hectares dentro do Bosque de Vincennes. Este zoológico possui como proposta a observação do comportamento animal dentro de um ambiente mais adaptado às suas necessidades.","ru":"Венсенский зоопарк является частью Государственного музея естествознания в Париже. Открыт в 1934 году; располагается на территории Венсенского леса. Общая площадь зоопарка составляет 14,5 гектаров.","ja":"パリ動物園 は、フランスのパリ12区にある動物園。別名ヴァンセンヌの森動物園。もしくはヴァンセンヌ動物園とも。","ko":"파리 동물원(프랑스어: Parc zoologique de Paris)은 흔히 뱅센 동물원(프랑스어: zoo de Vincennes)으로 불리며 이전에는 뱅센 숲 동물원(프랑스어: Bois de Vincennes Zoological Park)으로 알려졌었다. 이곳은 국립 자연사 박물관 소속 시설로, 파리 12구의 뱅센 숲 안에 위치해 있으며 면적은 14.5헥타르(36에이커)에 이른다. 이 동물원은 자르댕 데 플랑트 동물원의 동물사와 상호 보완하기 위해 설계되었으며, 더 적합한 환경에서 동물 행동을 관찰하는 데 중점을 두고 있다. 1934년 개장 이후로, \"빅 록\"(Big Rock, 프랑스어: Grand Rocher 그랑 로셰[*])으로 불리는 높이 65미터(213피트)의 거대한 인공 바위가 동물원의 상징이 되었고 동물원 로고에도 들어가 있다. 또한 면적 4,000제곱미터(43,000제곱피트)의 온실이 있어 열대 우림 기후를 재현하고 있다.","nl":"Het Parc Zoologique de Paris is een dierentuin in Parijs en bevindt zich in het Bois de Vincennes. In het Frans wordt de dierentuin ook wel het Parc Zoologique du Bois de Vincennes of Zoo de Vincennes genoemd. Deze dierentuin behoort tot de organisatie van het Muséum national d'histoire naturelle. Het Parc Zoologique de Paris werd geopend in 1934 en na een uitgebreide renovatie in 2014 heropend. Tegenwoordig is de dierentuin ingedeeld in vijf thematische gebieden, verspreid over een oppervlakte van 14,5 hectare. Er worden ongeveer 180 diersoorten gehouden.","zh-CN":"巴黎动物园，也叫文森动物园，坐落于法国巴黎市文森森林内，隶属于国家自然历史博物馆。动物园占地14.5公顷，包括一座65米高的石制假山以及一个占地4000平方米的热带植物温室。","zh-TW":"巴黎動物園，也叫文森動物園，坐落於法國巴黎市文森森林內，隸屬於國家自然歷史博物館。動物園占地14.5公頃，包括一座65米高的石制假山以及一個占地4000平方米的熱帶植物溫室。","it":"Il parco zoologico di Parigi, anche conosciuto come zoo di Vincennes, è un parco faunistico francese di 14,5 ettari situato nel 12º arrondissement di Parigi, a ovest del Bois de Vincennes, dipendente dal Museo nazionale di storia naturale di Francia. Fu progettato nel 1934 a completamento della Ménagerie du Jardin des Plantes per osservare il comportamento degli animali in cattività e la riproduzione di specie in via di estinzione nel loro ambiente nativo.","en":"The Paris Zoological Park, formerly known as the Bois de Vincennes Zoological Park, and commonly called the Vincennes Zoo, is a facility of the National Museum of Natural History, located in the 12th arrondissement of Paris, which covers an area of 14.5 hectares in the Bois de Vincennes. Designed to complement the Ménagerie du Jardin des plantes, this zoo is dedicated to the observation of animal behavior in a more suitable environment. Since its opening in 1934, it is remarkable for its large artificial 65 m (213 ft) high rock, iconic scenery of the park, visible from afar and popularly called the \"Big Rock\".","es":"El Parque Zoológico de París, conocido popularmente como Zoo de Vincennes por encontrarse en la entrada del bosque de Vincennes, es el principal jardín zoológico de París, la capital de Francia. Abierto al público por primera vez en 1934 y situado en el decimosegundo distrito de la ciudad, el parque se encuentra entre los límites de dos zonas verdes: el bosque de Vincennes y un parque llamado Pelouse de Reuilly. Cubriendo una superficie de 14,5 hectáreas, el zoo de Vincennes es uno de los cuatro parques zoológicos que dependen del Museo Nacional de Historia Natural de Francia.","fr":"Le parc zoologique de Paris, anciennement parc zoologique du bois de Vincennes, familièrement appelé zoo de Vincennes, est un parc zoologique français de 14,5 hectares, faisant partie du Muséum national d'histoire naturelle, situé dans l'ouest du bois de Vincennes, attenant au 12e arrondissement de Paris. Conçu en 1934, en complément de la ménagerie du Jardin des plantes, ce zoo a pour vocation l'observation du comportement animal en captivité et la reproduction d'espèces menacées pour être réintroduites dans leurs milieux d'origine.","de":"Der Parc zoologique de Paris ist der größte Zoo von Paris, gelegen im Bois de Vincennes."},"wiki":{"pt":"https://pt.wikipedia.org/wiki/Jardim_Zool%C3%B3gico_de_Paris","ru":"https://ru.wikipedia.org/wiki/%D0%92%D0%B5%D0%BD%D1%81%D0%B5%D0%BD%D1%81%D0%BA%D0%B8%D0%B9_%D0%B7%D0%BE%D0%BE%D0%BF%D0%B0%D1%80%D0%BA","ja":"https://ja.wikipedia.org/wiki/%E3%83%91%E3%83%AA%E5%8B%95%E7%89%A9%E5%9C%92","ko":"https://ko.wikipedia.org/wiki/%ED%8C%8C%EB%A6%AC_%EB%8F%99%EB%AC%BC%EC%9B%90","nl":"https://nl.wikipedia.org/wiki/Parc_Zoologique_de_Paris","zh-CN":"https://zh.wikipedia.org/wiki/%E5%B7%B4%E9%BB%8E%E5%8A%A8%E7%89%A9%E5%9B%AD","zh-TW":"https://zh.wikipedia.org/wiki/%E5%B7%B4%E9%BB%8E%E5%8A%A8%E7%89%A9%E5%9B%AD","it":"https://it.wikipedia.org/wiki/Parco_zoologico_di_Parigi","en":"https://en.wikipedia.org/wiki/Paris_Zoological_Park","es":"https://es.wikipedia.org/wiki/Parque_Zool%C3%B3gico_de_Par%C3%ADs","fr":"https://fr.wikipedia.org/wiki/Parc_zoologique_de_Paris","de":"https://de.wikipedia.org/wiki/Parc_zoologique_de_Paris"},"site":"https://www.parczoologiquedeparis.fr","adresse":"croisement de l’avenue Daumesnil et de la route de la Ceinture du Lac, 75012 Paris"},{"id":"wd-Q1573359","cat":"patrimoine","ville":"saint-mande","nom":{"fr":"Place de la Nation","en":"Place de la Nation","es":"Plaza de la Nación","de":"Place de la Nation","it":"Place de la Nation","pt":"Place de la Nation","nl":"Place de la Nation","pl":"Place de la Nation","ru":"Площадь Нации","uk":"Площа Нації","ar":"ميدان لاناسيون (باريس)","he":"פלאס דה לה נסיון","tr":"Nation Meydanı","sv":"Place de la Nation","nb":"Place de la Nation","fi":"Place de la Nation","cs":"Place de la Nation","sk":"Place de la Nation","hr":"Place de la nation","sr":"Трг Нације","ca":"Place de la Nation","eu":"Nazioaren plaza","zh-CN":"民族广场","zh-TW":"民族廣場","ja":"ナシオン広場","vi":"Quảng trường Nation","id":"Place de la Nation","ms":"Place de la Nation"},"lat":48.848333,"lon":2.395833,"prix":{"type":"libre"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Place_de_la_Nation%2C_Paris_September_2014.jpg/960px-Place_de_la_Nation%2C_Paris_September_2014.jpg","page":"https://commons.wikimedia.org/wiki/File:Place_de_la_Nation,_Paris_September_2014.jpg","auteur":"Guilhem Vellut from Tokyo, Japan","licence":"CC BY 2.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q1573359"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Place_de_la_Nation_(Paris)"},{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/way/703150476"}],"recupere":"2026-11-14","court":{"fr":"place de Paris, en France","en":"square in Paris, France","es":"plaza en París, Francia","de":"Platz in Paris‎","it":"piazza di Parigi","pt":"Praça em Paris, França","nl":"plein in Parijs, Frankrijk","pl":"plac w Paryżu","ru":"Площадь в Париже, Франция","ar":"ميدان في فرنسا","he":"כיכר בפריז, צרפת","tr":"Paris'te meydan","nb":"plass i Paris","cs":"Národní náměstí v Paříži","sk":"námestie v Paríži","hr":"trg u Parizu","ca":"plaça a París, França","zh-CN":"巴黎广场"},"long":{"pt":"A Place de la Nation é uma praça circular situada à oeste de Paris, entre a Praça da Bastilha e a Bois de Vincennes, ao longo de uma parte dos arrondissements 11 e 12. Mais conhecida por ter tido uma das guilhotinas mais ativas durante a Revolução Francesa, esta praça foi renomeada para Place de la Nation em 14 de julho de 1880. Possui uma grande escultura de bronze chamada de 'Triunfo da República', em seus arredores há lojas e um jardim de flores.","zh-CN":"民族广场 是法国巴黎的一个广场，位于第十一区和第十二区边界。最初名为“place du Trône”，法国革命期间的1792年8月10日，更名为“place du Trône-Renversé”，广场南半部还设置了断头台，1794年7月25日，法国诗人安德烈·舍尼埃在此被送上断头台。1880年7月14日国庆节时改用今名。这里设有巴黎地铁民族站。","ar":"يقع ميدان لاناسيون أو ميدان الامة في الجانب الشرقي من باريس، بين ميدان الباستيل وغابة فانسين. حصل الميدان على اسمه الحالي في الرابع عشر من يوليو 1880، في يوم العيد الوطني لفرنسا، تحت الجمهورية الثالثة.","ru":"Площадь Нации — одна из площадей Парижа.","zh-TW":"民族廣場 是法國巴黎的一個廣場，位於第十一區和第十二區邊界。最初名為「place du Trône」，法國革命期間的1792年8月10日，更名為「place du Trône-Renversé」，廣場南半部還設置了斷頭台，1794年7月25日，法國詩人安德烈·舍尼埃在此被送上斷頭台。1880年7月14日國慶節時改用今名。這裡設有巴黎地鐵民族站。","nl":"De Place de la Nation, vroeger Place du Trône, daarna Place du Trône-Renversé, is een groot rond plein in de Franse hoofdstad Parijs, gelegen op de grens van het 11e en 12e arrondissement. Het plein is vernoemd naar de Franse natie. Centraal op het plein staat het monument Triomphe de la République met een standbeeld van Marianne, de personificatie van Frankrijk. Net buiten het plein staan aan weerszijden van de Cours de Vincennes twee hoge zuilen die de entree naar het plein markeren, de Barrière du Trône.","en":"The Place de la Nation is a circle on the eastern side of Paris, between the Place de la Bastille and the Bois de Vincennes, on the border of the 11th and 12th arrondissements. The square acquired its current name on Bastille Day, 14 July 1880, under the Third Republic.","es":"La Plaza de la Nación es una glorieta parisina situada en los distritos once y doce. Una escultura de Jules Dalou, titulada «El Triunfo de la República», adorna su centro.","fr":"La place de la Nation, ancienne « place du Trône » puis « place du Trône-Renversé », est une place située à la limite des 11e et 12e arrondissements de Paris.","it":"La Place de la Nation è una rotonda sul lato orientale di Parigi, tra Place de la Bastille e il Bois de Vincennes, al confine tra l' XI e il XII arrondissement.","de":"Die Place de la Nation ist ein Platz im Osten von Paris an der Grenze zwischen 11. und 12. Arrondissement und dem 44. Quartier Sainte-Marguerite und dem 46. Quartier de Picpus. Er ist einer der größten und wichtigsten Verkehrsknotenpunkte der Stadt. Der Platz bekam seinen Namen anlässlich des Nationalfeiertags am 14. Juli 1880, ab dem auf allen öffentlichen Gebäuden die Devise Freiheit, Gleichheit, Brüderlichkeit angezeigt wurde."},"wiki":{"pt":"https://pt.wikipedia.org/wiki/Place_de_la_Nation","zh-CN":"https://zh.wikipedia.org/wiki/%E6%B0%91%E6%97%8F%E5%B9%BF%E5%9C%BA_(%E5%B7%B4%E9%BB%8E)","ar":"https://ar.wikipedia.org/wiki/%D9%85%D9%8A%D8%AF%D8%A7%D9%86_%D9%84%D8%A7%D9%86%D8%A7%D8%B3%D9%8A%D9%88%D9%86_(%D8%A8%D8%A7%D8%B1%D9%8A%D8%B3)","ru":"https://ru.wikipedia.org/wiki/%D0%9F%D0%BB%D0%BE%D1%89%D0%B0%D0%B4%D1%8C_%D0%9D%D0%B0%D1%86%D0%B8%D0%B8","zh-TW":"https://zh.wikipedia.org/wiki/%E6%B0%91%E6%97%8F%E5%B9%BF%E5%9C%BA_(%E5%B7%B4%E9%BB%8E)","nl":"https://nl.wikipedia.org/wiki/Place_de_la_Nation","en":"https://en.wikipedia.org/wiki/Place_de_la_Nation","es":"https://es.wikipedia.org/wiki/Plaza_de_la_Naci%C3%B3n","fr":"https://fr.wikipedia.org/wiki/Place_de_la_Nation_(Paris)","it":"https://it.wikipedia.org/wiki/Place_de_la_Nation","de":"https://de.wikipedia.org/wiki/Place_de_la_Nation"}},{"id":"wd-Q2060889","cat":"parcs","ville":"saint-mande","nom":{"fr":"Coulée verte René-Dumont","en":"Coulée verte René-Dumont","es":"Coulée verte René-Dumont","de":"Coulée verte René-Dumont","it":"Coulée verte René-Dumont","pt":"Coulée verte René-Dumont","nl":"Coulée verte René-Dumont","he":"פרומנד פלנטה-הטיילת הירוקה של רנה דומון","tr":"Coulée verte René-Dumont","el":"Πεζόδρομος Ρενέ-Ντυμόν","sv":"Coulée verte René-Dumont","nb":"Coulée verte René-Dumont","fi":"Coulée verte René-Dumont","cs":"Coulée verte René-Dumont","ca":"Coulée verte René-Dumont","zh-CN":"露天植物园平台","zh-TW":"露天植物園平臺","ja":"プロムナード・プランテ","ko":"프롬나드 플랑테","vi":"Coulée verte René-Dumont","id":"Coulée verte René-Dumont","ms":"Coulée verte René-Dumont"},"lat":48.849572,"lon":2.3711,"prix":{"type":"libre"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Promenade_plant%C3%A9e%2C_Paris_August_2009_%2810%29.jpg/960px-Promenade_plant%C3%A9e%2C_Paris_August_2009_%2810%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Promenade_plant%C3%A9e,_Paris_August_2009_(10).jpg","auteur":"jean-louis Zimmermann from Moulins, FRANCE","licence":"CC BY 2.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q2060889"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Coul%C3%A9e_verte_Ren%C3%A9-Dumont"},{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/way/35802063"}],"recupere":"2026-11-14","court":{"fr":"espace vert de Paris, France","en":"urban park in Paris, France","es":"jardín público lineal de París, Francia","de":"Stadtpark in Paris, Frankreich","nl":"wandelpark gelegen in Parijs","he":"פארק ליניארי ונתיב הליכה ירוק ברובע ה-12 בפריז, צרפת","cs":"park v Paříži","ja":"パリの緑道","vi":"không gian xanh ở Paris, Pháp","id":"Taman di Paris, Prancis"},"long":{"pt":"O corredor verde Renée-Dumont, antigamente conhecido como Promenade Plantée, é um parque linear no 12.º arrondissement de Paris, na França.","ko":"프롬나드 플랑테(프랑스어: Promenade plantée→가로수 산책길) 또는 쿨레 베르트(Coulée verte→초록 오솔길)는 파리 12구역에 위치한 버려진 고가철도 위에 지어진 4.7km 길이의 선형 공원이다. 1993년 완공하였다.","zh-CN":"勒内·杜蒙绿色长廊，也称绿荫步道，是法国巴黎十二区的一条4.7公里的线性公园，它在废弃的铁道设施基础上建立，建成于1993年。这条绿色长廊包含有高架公园、普通道路、隧道和穿越公园的小径。","zh-TW":"勒內·杜蒙綠色長廊，也稱綠蔭步道，是法國巴黎十二區的一條4.7公里的線性公園，它在廢棄的鐵道設施基礎上建立，建成於1993年。這條綠色長廊包含有高架公園、普通道路、隧道和穿越公園的小徑。","nl":"De Coulée verte René-Dumont of Promenade plantée, kortweg Coulée verte of Promenade, is een verhoogd park, 4,7 km lang, dat op het Parijse deel van de Ligne de Vincennes uit de 19e eeuw is aangelegd en die op 14 december 1969 buiten gebruik is gesteld. Het park ligt in het 12e arrondissement, loopt over afwisselend viaducten, spoordijken, bruggen, gelijkvloerse ruimten, door twee tunnels en werd in 1993 geopend.","fr":"La coulée verte René-Dumont, anciennement Promenade plantée, est une voie verte et un parc linéaire du 12e arrondissement de Paris en France.","de":"Die Coulée verte René-Dumont ist ein 4,5 Kilometer langer Parkwanderweg, der zunächst entlang der Avenue Daumesnil im 12. Arrondissement von Paris führt. Er beginnt nahe dem Platz Place de la Bastille, der am U-Bahnhof Bastille von den Linien 1, 5 und 8 der Métro Paris erschlossen wird. Weiter östlich unterquert er die ebenerdig angelegte Métrostation Bel-Air der Linie 6, sein östliches Ende wird über die Haltestelle Montempoivre der Straßenbahnlinie T3a erreicht.","it":"La Promenade plantée è un lungo spazio verde adibito a passeggiata pedonale e parco pubblico situato nel XII arrondissement di Parigi, in Francia. Il suo nome ufficiale è La Coulée verte René-Dumont.","es":"El Sendero verde René-Dumont,, es un jardín público lineal situado en el XII Distrito de París siguiendo el recorrido de una antigua línea de tren. Parte del trazado trascurre a 10 metros de altura sobre el viaducto de las Artes.","en":"The Coulée verte René-Dumont or Promenade plantée René-Dumont is a 4.7 km (2.9 mi) elevated linear park built on top of obsolete railway infrastructure in the 12th arrondissement of Paris, France. It was inaugurated in 1993."},"wiki":{"pt":"https://pt.wikipedia.org/wiki/Coul%C3%A9e_verte_Ren%C3%A9-Dumont","ko":"https://ko.wikipedia.org/wiki/%ED%94%84%EB%A1%AC%EB%82%98%EB%93%9C_%ED%94%8C%EB%9E%91%ED%85%8C","zh-CN":"https://zh.wikipedia.org/wiki/%E5%8B%92%E5%86%85%C2%B7%E6%9D%9C%E8%92%99%E7%BB%BF%E8%89%B2%E9%95%BF%E5%BB%8A","zh-TW":"https://zh.wikipedia.org/wiki/%E5%8B%92%E5%86%85%C2%B7%E6%9D%9C%E8%92%99%E7%BB%BF%E8%89%B2%E9%95%BF%E5%BB%8A","nl":"https://nl.wikipedia.org/wiki/Coul%C3%A9e_verte_Ren%C3%A9-Dumont","fr":"https://fr.wikipedia.org/wiki/Coul%C3%A9e_verte_Ren%C3%A9-Dumont","de":"https://de.wikipedia.org/wiki/Coul%C3%A9e_verte_Ren%C3%A9-Dumont","it":"https://it.wikipedia.org/wiki/Promenade_plant%C3%A9e","es":"https://es.wikipedia.org/wiki/Coul%C3%A9e_verte_Ren%C3%A9-Dumont","en":"https://en.wikipedia.org/wiki/Coul%C3%A9e_verte_Ren%C3%A9-Dumont"},"site":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772","horaires":"May 1-Aug: 31 07:00-21:30; Sep 1-Sep 30: 07:00-20:30; Oct 1-Oct 31: Mo-Fr 08:19:30; Sa-Di 09:00-19:30"},{"id":"wd-Q1094332","cat":"musees","ville":"saint-mande","nom":{"fr":"Musée de l'histoire de l'immigration","en":"Cité nationale de l'histoire de l'immigration","de":"Cité nationale de l’histoire de l’immigration","it":"Museo della storia dell'immigrazione","nl":"Cité nationale de l'histoire de l'immigration","ru":"Музей иммиграции","el":"Εθνικό Μουσείο Ιστορίας της μετανάστευσης","fi":"Maahanmuuton historian museo","cs":"Cité nationale de l'histoire de l'immigration","ro":"Cité nationale de l’histoire de l’immigration","sl":"Narodni muzej zgodovine priseljevanja","ca":"Ciutat Nacional de la Història de la Immigració","zh-CN":"国立移民历史城","ja":"国立移民史博物館"},"lat":48.835278,"lon":2.409444,"prix":{"type":"payant"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/L%27exposition_permanente_de_la_CNHI.jpg/960px-L%27exposition_permanente_de_la_CNHI.jpg","page":"https://commons.wikimedia.org/wiki/File:L%27exposition_permanente_de_la_CNHI.jpg","auteur":"Jean-Pierre Dalbéra","licence":"CC BY 2.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q1094332"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Mus%C3%A9e_de_l'Histoire_de_l'immigration"},{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/node/4908819676"},{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/ae30be51-5ecd-3c75-bbc3-43eba3fb16f6"},{"nom":"DATAtourisme · Choose Paris Region","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/7a24e5b6-06e8-3a92-a183-3a0ca529c8a2"}],"recupere":"2026-11-14","court":{"fr":"musée à Paris, France","en":"museum in Paris, France","de":"Museum in Frankreich","it":"museo in Francia","nl":"museum in Frankrijk","ru":"музей в Париже","he":"מוזיאון בצרפת","el":"Μουσείο στο Παρίσι, Γαλλία","sv":"museum i Frankrike","fi":"museo Ranskassa","cs":"muzeum v Paříži","sl":"muzej v Parizu (Francija)","ca":"museu de París"},"long":{"ru":"Музей иммиграции открылся 10 октября 2007 года.","ja":"国立移民史博物館 は、フランスにおける主に19世紀以降の移民の歴史を紹介する博物館である。","zh-CN":"国立移民历史城 是一座以移民史为主题的博物馆，位于巴黎十二区。博物馆每天开放，星期一除外；一入场费用全免。 建立该博物馆的设想在1989年由阿尔及利亚移民Zaïr Kedadouche提出，并得到历史学家皮埃尔·米尔扎和Gérard Noiriel的支持。博物馆位于镀金门宫里面，而那里原本是国立非洲大洋洲艺术博物馆的所在地。","zh-TW":"國立移民歷史城 是一座以移民史為主題的博物館，位於巴黎十二區。博物館每天開放，星期一除外；一入場費用全免。 建立該博物館的設想在1989年由阿爾及利亞移民Zaïr Kedadouche提出，並得到歷史學家皮埃爾·米爾扎和Gérard Noiriel的支持。博物館位於鍍金門宮裡面，而那裡原本是國立非洲大洋洲藝術博物館的所在地。","de":"Die Cité nationale de l’histoire de l’immigration (CNHI) ist ein Museum der Immigration nach Frankreich, das am 10. Oktober 2007 nach zwanzigjähriger Vorbereitung in Paris eingeweiht wurde.","en":"The Musée nationale de l'histoire de l'immigration is a museum of immigration history located in the 12th arrondissement of Paris at 293, avenue Daumesnil. The nearest métro station is Porte Dorée. It is open Tuesday through Friday from 10 a.m. to 5:30 p.m. and weekends from 10 a.m. to 7 p.m.; there is an admission fee.","fr":"Le musée de l’Histoire de l’immigration est un musée national français situé dans le palais de la Porte-Dorée dans le 12e arrondissement, à l'est de Paris. Il est ouvert au public depuis octobre 2007 et a été officiellement inauguré le 15 décembre 2014 par le président François Hollande, sept ans après son ouverture. Il est administré par l'« établissement public du palais de la Porte-Dorée » depuis janvier 2012. Sa dénomination officielle est « Musée national de l'histoire et des cultures de l'immigration »."},"wiki":{"ru":"https://ru.wikipedia.org/wiki/%D0%9C%D1%83%D0%B7%D0%B5%D0%B9_%D0%B8%D0%BC%D0%BC%D0%B8%D0%B3%D1%80%D0%B0%D1%86%D0%B8%D0%B8_(%D0%9F%D0%B0%D1%80%D0%B8%D0%B6)","ja":"https://ja.wikipedia.org/wiki/%E5%9B%BD%E7%AB%8B%E7%A7%BB%E6%B0%91%E5%8F%B2%E5%8D%9A%E7%89%A9%E9%A4%A8","zh-CN":"https://zh.wikipedia.org/wiki/%E5%9B%BD%E7%AB%8B%E7%A7%BB%E6%B0%91%E5%8E%86%E5%8F%B2%E5%9F%8E","zh-TW":"https://zh.wikipedia.org/wiki/%E5%9B%BD%E7%AB%8B%E7%A7%BB%E6%B0%91%E5%8E%86%E5%8F%B2%E5%9F%8E","de":"https://de.wikipedia.org/wiki/Cit%C3%A9_nationale_de_l%E2%80%99histoire_de_l%E2%80%99immigration","en":"https://en.wikipedia.org/wiki/Cit%C3%A9_nationale_de_l'histoire_de_l'immigration","fr":"https://fr.wikipedia.org/wiki/Mus%C3%A9e_de_l'Histoire_de_l'immigration"},"site":"https://www.histoire-immigration.fr/","adresse":"293 Avenue Daumesnil, 75012","tel":"+33 1 53 59 58 60","horaires":"Tu-Fr 10:00-17:30; Sa-Su 10:00-19:00"},{"id":"osm-n2978102520","cat":"restaurants","ville":"saint-mande","nom":"Dream Sushi","lat":48.853183,"lon":2.422504,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/node/2978102520"}],"recupere":"2026-11-14","site":"https://www.dreamsushi93m.fr","adresse":"8 Rue de la République, 93100","tel":"+33 1 48 59 04 79","horaires":"Mo-Fr 11:30-15:00,18:30-23:00; Sa-Su,PH 18:30-23:00","fauteuil":"no","cuisine":"japanese"},{"id":"osm-w205013566","cat":"cafes","ville":"saint-mande","nom":"Le Métron'Home","lat":48.846059,"lon":2.420273,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/way/205013566"}],"recupere":"2026-11-14","site":"https://metronhome.metro.bar/","adresse":"113 Avenue de Paris, 94160 Saint-Mandé","tel":"+33 1 43 28 00 65","horaires":"Mo-Fr 07:00-23:45; Sa 09:00-23:45","fauteuil":"no","cuisine":"french"},{"id":"osm-n2334286001","cat":"restaurants","ville":"saint-mande","nom":"Les Zygomates","lat":48.835866,"lon":2.398331,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/node/2334286001"}],"recupere":"2026-11-14","site":"http://www.leszygomates.fr","adresse":"7 Rue de Capri, 75012","tel":"+33140199304","horaires":"Tu-Sa 12:00-14:00, We-Sa 19:30-22:00; Su,Mo off","fauteuil":"no","cuisine":"french"},{"id":"dt-323f0830-648b-3e55-9ce7-f4ee8d809e57","cat":"hotels","ville":"saint-mande","nom":"Hotel Cis Paris Ravel","lat":48.841835,"lon":2.411953,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/323f0830-648b-3e55-9ce7-f4ee8d809e57"}],"recupere":"2026-11-14","long":{"fr":"Séjournez au cœur de la capitale dans l'une des 108 chambres individuelles ou multiples de l'Hotel Cis Paris Ravel. Profitez du restaurant de 250 places ou du self-service de 140 places pour vos repas. Organisez vos réunions dans l'une des 20 salles pouvant accueillir de 8 à 230 personnes. Que ce soit pour un voyage en groupe avec des visites prévues, l'établissement saura répondre à vos besoins avec un service dédié et de qualité !"},"site":"https://www.hotel-cis-paris-ravel.com/fr","adresse":"6 avenue Maurice Ravel, 75012 Paris","labels":["Tourisme & Handicap auditif","Tourisme & Handicap visuel","2 étoiles","Tourisme & Handicap mental"],"majSource":"2026-09-01"},{"id":"dt-5f410c9a-e5a6-3bee-a530-fd06e5d67314","cat":"hotels","ville":"saint-mande","nom":"Novotel Paris Centre Bercy","lat":48.838654,"lon":2.380449,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/5f410c9a-e5a6-3bee-a530-fd06e5d67314"}],"recupere":"2026-11-14","long":{"fr":"Le Novotel Paris Centre Bercy, hôtel 4 étoiles en face de l'Accor Arena, vous donne un accès privilégié aux concerts et événements sportifs. Proche du métro « Bercy », Paris est à votre portée. Gare de Lyon à 10 min à pied pour aller à Disneyland Paris. Chambres rénovées, climatisées, Wifi gratuit. Profitez du restaurant avec terrasse ou du bar, organisez vos réunions dans l'une des 7 salles. Parking public payant à proximité. Personnel compétent pour un séjour mémorable."},"site":"https://all.accor.com/hotel/0935/index.fr","adresse":"85 rue de Bercy, 75012 Paris","labels":["Tourisme & Handicap auditif","Tourisme & Handicap visuel","4 étoiles","Clef Verte"],"majSource":"2026-09-01"},{"id":"dt-fae2fe37-3386-3b69-92ec-93de90295b26","cat":"hotels","ville":"saint-mande","nom":"Hôtel du Printemps","lat":48.846033,"lon":2.401841,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/fae2fe37-3386-3b69-92ec-93de90295b26"}],"recupere":"2026-11-14","long":{"fr":"Idéalement situé à Nation, l'Hôtel du Printemps séduit par son charme discret et son accueil chaleureux. Ses chambres rénovées, non-fumeurs, offrent parquet et double vitrage pour plus de confort. Wifi, TV écran plat et climatisation réversible sont disponibles. Proche de 4 lignes de métro et du RER A, l'accès aux sites touristiques est facile. Un parking à proximité facilite votre séjour. Découvrez Paris sereinement dans cet environnement calme et pratique."},"site":"http://www.hotel-paris-printemps.com/","adresse":"80 boulevard Picpus, 75012 Paris","labels":["2 étoiles","Clef Verte"],"majSource":"2026-09-01"},{"id":"dt-4fa04832-c2b3-3362-a5ba-21d335bdefb0","cat":"hotels","ville":"saint-mande","nom":"Campanile Paris XII - Bercy Village","lat":48.83511,"lon":2.387644,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/4fa04832-c2b3-3362-a5ba-21d335bdefb0"}],"recupere":"2026-11-14","long":{"fr":"L'hôtel Campanile Paris XII - Bercy Village, situé à l'est de Paris, est idéalement placé pour découvrir la Ville Lumière. À proximité du parc de Bercy et de ses 4 jardins, ainsi que du charmant Village « Cour Saint Emilion » avec ses boutiques et restaurants, les balades sont assurées. Sa proximité avec le métro (ligne 14) permet de rejoindre la Gare de Lyon en 2 stations et Bercy Arena en 10 minutes à pied. Profitez ainsi des spectacles et concerts en toute simplicité."},"site":"https://www.hotelbercy.com/","adresse":"19 rue Baron Le Roy, 75012 Paris","labels":["3 étoiles","Clef Verte"],"majSource":"2026-09-01"},{"id":"dt-a5592c29-1864-3557-916d-b274130092eb","cat":"hotels","ville":"saint-mande","nom":"Zazie Hôtel","lat":48.84534,"lon":2.383296,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/a5592c29-1864-3557-916d-b274130092eb"}],"recupere":"2026-11-14","long":{"fr":"Idéalement situé entre Bastille et Nation, près des Jardins de Reuilly et du Marché Aligre, le Zazie Hôtel profite d'un emplacement privilégié. Proche de la Gare de Lyon, il offre un accès facile aux sites touristiques. Les chambres, simples, doubles, twin, triples, mitoyennes ou communicantes, sont modernes avec salle de bains privative, télévision, téléphone et Wifi gratuit. Savourez un petit déjeuner buffet délicieux avec des produits locaux de qualité."},"site":"https://www.zaziehotel.paris/","adresse":"3 rue Chaligny, 75012 Paris","labels":["2 étoiles","Clef Verte"],"majSource":"2026-09-01"},{"id":"dt-e4168261-36aa-37a1-9331-43deb16ec6b6","cat":"hotels","ville":"saint-mande","nom":"Ibis Styles Paris Bercy","lat":48.838352,"lon":2.381021,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/e4168261-36aa-37a1-9331-43deb16ec6b6"}],"recupere":"2026-11-14","long":{"fr":"L'hôtel Ibis Styles Paris Bercy est situé à quelques pas de l'Accor Arena et de la gare de Lyon. Cet hôtel atypique, offre une décoration au design street art. Les chambres sont modernes et lumineuses. Le restaurant dispose d'une terrasse face au parc de Bercy. Il sert une cuisine française, simple et innovante. Le petit déjeuner est inclus dans le prix. Le bar est spacieux et abrite un piano. Un espace de jeux est destiné aux enfants."},"site":"https://all.accor.com/hotel/0941/index.fr.shtml","adresse":"77 rue de Bercy, 75012 Paris","labels":["3 étoiles","Clef Verte"],"majSource":"2026-09-01"},{"id":"dt-d285d4cb-f57b-3c4d-af74-fc57104cd4a8","cat":"loisirs","ville":"saint-mande","nom":"Piscine Roger Le Gall","lat":48.84175,"lon":2.412801,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/d285d4cb-f57b-3c4d-af74-fc57104cd4a8"}],"recupere":"2026-11-14","long":{"fr":"La piscine Roger Le Gall, à la Porte de Vincennes, est très appréciée des Parisiens pour son équipement sportif de qualité. Ouverts au public, deux bassins sont disponibles : un de 50 m sur 15 et un autre de 25 m sur 12,5 réservé aux clubs. Construite en 1967, elle accueille tous les niveaux de nageurs. En été, le toit s'ouvre pour laisser place à un bain de soleil sur la pelouse. Les adeptes du naturisme sont également bienvenus les lundi, mercredi et vendredi soirs."},"site":"https://www.paris.fr/","adresse":"34 boulevard Carnot, 75012 Paris","majSource":"2026-09-01"},{"id":"dt-2c2099f6-bef2-3115-9263-160b27cd7d87","cat":"restaurants","ville":"saint-mande","nom":"Le Chalet du Lac","lat":48.842885,"lon":2.422097,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/2c2099f6-bef2-3115-9263-160b27cd7d87"}],"recupere":"2026-11-14","long":{"fr":"Le Chalet du Lac, lieu mythique ayant accueilli le premier concert parisien des Sex Pistols en 1976, renoue avec l'esprit du bal. Ouvert en 1904, il a été entièrement restauré en 2003 pour retrouver son charme Belle Époque. Cette institution organise désormais des soirées et des thés dansants, mettant en avant les danses de salon. Une véritable invitation à revivre l'ambiance festive et élégante d'autrefois !"},"site":"https://chaletdulac.com/","adresse":"Orée du bois de Vincennes - Avenue Anna Politkovskaïa, 75012 Paris","majSource":"2026-09-01"},{"id":"dt-10b03091-657d-3a8a-a84e-60cda11ad4e3","cat":"cafes","ville":"saint-mande","nom":"Raimo","lat":48.839825,"lon":2.39832,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/10b03091-657d-3a8a-a84e-60cda11ad4e3"}],"recupere":"2026-11-14","long":{"fr":"Depuis 1947, le glacier parisien Raimo est réputé. En 2008, la famille Raimondo transmet son savoir-faire à trois passionnés de gastronomie pour garantir la qualité. Avec plus de 120 parfums de glaces, crèmes glacées et sorbets, Raimo répond à toutes les envies, certains étant saisonniers. Classé parmi les meilleurs glaciers de la capitale par Sortiraparis.com en 2013, Raimo est présent dans plusieurs quartiers parisiens. Venez découvrir leur originalité dans l'un de leurs points de vente."},"site":"https://www.raimo.fr/","adresse":"59-63 boulevard de Reuilly, 75012 Paris","majSource":"2026-09-01"},{"id":"dt-c91740fa-4a8d-335f-aa02-2a65cfa64d91","cat":"animaux","ville":"saint-mande","nom":"Aquarium tropical","lat":48.835526,"lon":2.409254,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/c91740fa-4a8d-335f-aa02-2a65cfa64d91"}],"recupere":"2026-11-14","long":{"fr":"Le Palais de la Porte Dorée, monument historique classé, abrite l'Aquarium tropical et le musée de l'histoire de l'immigration. Avec près de 5000 animaux, des eaux d’Asie aux faunes exotiques d’Afrique et d’Amérique du Sud, les visiteurs découvrent crocodiles, requins et piranhas. Depuis 2007, le site accueille également deux alligators albinos, symboles de la diversité culturelle en France. Une expérience enrichissante pour toute la famille!"},"site":"https://www.aquarium-tropical.fr/","adresse":"Palais de la Porte Dorée - 293 avenue Daumesnil, 75012 Paris","majSource":"2026-09-01"},{"id":"dt-83c83a81-040c-3af3-beca-1c77708b79a3","cat":"patrimoine","ville":"saint-mande","nom":"Paroisse du Saint-Esprit","lat":48.838467,"lon":2.39803,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/83c83a81-040c-3af3-beca-1c77708b79a3"}],"recupere":"2026-11-14","long":{"fr":"Située dans le quartier de Daumesnil, l’église conçue par l’architecte Paul Tournon, dévoile sa crypte dès 1929. Bâtie en béton armé, elle dévoile une nef carrée surmontée d'une majestueuse coupole de 22 mètres de diamètre pour 33 mètres de hauteur. À l'intérieur, mosaïques, vitraux, peintures, sculptures et ferronneries forment un décor classé monument historique. Des concerts d'orgue et de musique classique y sont régulièrement donnés pour animer ces murs chargés d'histoire."},"site":"http://www.st-esprit.org/","adresse":"186 avenue Daumesnil, 75012 Paris","majSource":"2026-09-01"},{"id":"dt-fb7031ea-d36d-31d8-8f49-7499e376181a","cat":"parcs","ville":"saint-mande","nom":"Square Sarah Bernhardt","lat":48.849346,"lon":2.40402,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/fb7031ea-d36d-31d8-8f49-7499e376181a"}],"recupere":"2026-11-14","long":{"fr":"Le splendide square en question est un joyau naturel au cœur de la ville. Avec plus de 200 arbres de 50 espèces différentes, des ifs taillés en cône et de magnifiques massifs de fleurs, il attire par sa biodiversité exceptionnelle. C'est un havre de paix où règne une atmosphère sereine, propice à la contemplation. La nature y est mise en valeur dans toute sa splendeur, offrant un cadre idyllique pour se ressourcer et profiter de moments de calme et de beauté."},"site":"https://www.paris.fr/","adresse":"2 rue de Buzenval, 75020 Paris","majSource":"2026-09-01"},{"id":"dt-3720a5dc-a3dd-3352-8c26-2b86efeb9488","cat":"shopping","ville":"saint-mande","nom":"Le Siga-Siga - La boutique sans argent","lat":48.836388,"lon":2.400333,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/3720a5dc-a3dd-3352-8c26-2b86efeb9488"}],"recupere":"2026-11-14","long":{"fr":"Venez découvrir le Siga-Siga, un lieu unique dédié au don collaboratif, implanté dans l'ancienne gare de Reuilly, dans le 12e arrondissement. Déposez-y vos objets transportables (vêtements, vaisselle, jeux, jouets, livres...) dont vous n'avez plus besoin, et repartez avec de nouveaux articles... le tout gratuitement ! Profitez également d'un moment de détente autour d'un café ou d'un thé. En un geste généreux, participez à cette belle initiative solidaire !"},"site":"http://laboutiquesansargent.org/","adresse":"Ancienne gare de Reuilly - 181 avenue Daumesnil, 75012 Paris","majSource":"2026-09-01"},{"id":"dt-0a2361ff-a3e6-3451-a09c-9c7668940b11","cat":"loisirs","ville":"saint-mande","nom":"Studio Massaro","lat":48.849274,"lon":2.394008,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/0a2361ff-a3e6-3451-a09c-9c7668940b11"}],"recupere":"2026-11-14","long":{"fr":"Découvrez un centre de danse et formation dédié aux danses sud-américaines telles que le tango argentin, la salsa, la samba, et la danse brésilienne. Apprenez à maîtriser ces danses envoûtantes et passionnées dans une ambiance chaleureuse et conviviale. Que vous soyez débutant ou danseur confirmé, nos cours s'adaptent à tous les niveaux pour vous faire progresser tout en vous amusant. Rejoignez-nous pour un voyage au cœur de la culture et de la musique latino-américaine !"},"site":"http://www.studio-massaro.fr/","adresse":"290 boulevard Voltaire, 75011 Paris","majSource":"2026-09-01"},{"id":"dt-eae33e8d-3659-377e-b256-da05d3588754","cat":"patrimoine","ville":"saint-mande","nom":"Espace Reuilly","lat":48.842707,"lon":2.38955,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/eae33e8d-3659-377e-b256-da05d3588754"}],"recupere":"2026-11-14","long":{"fr":"L'Espace Reuilly, entre la gare de Lyon et la place de la Nation, est parfait pour tous vos événements. Avec une grande salle jusqu'à 740 personnes, un auditorium et une salle de réception, il convient à tout type d'événement. Sa localisation stratégique offre un accès facile en voiture, métro ou bus, dans toute la capitale. Son cadre moderne et élégant sublime chaque événement pour des souvenirs mémorables. Optez pour l'Espace Reuilly et assurez le succès de votre événement !"},"site":"https://www.mairie12.paris.fr/","adresse":"1 rue Riesener, 75012 Paris","majSource":"2026-09-01"},{"id":"dt-3e84f7ec-4398-356b-9d46-02d50cb3579d","cat":"marches","ville":"saint-mande","nom":"Marché Bercy","lat":48.835506,"lon":2.387196,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/3e84f7ec-4398-356b-9d46-02d50cb3579d"}],"recupere":"2026-11-14","long":{"fr":"Situé à proximité, Bercy Village est un marché incontournable pour les amateurs de produits frais et locaux. Ce charmant marché propose une large sélection de fruits et légumes biologiques, parfaits pour une alimentation saine. Que ce soit pour faire ses courses ou flâner entre les étals colorés, Bercy Village est une oasis pour les papilles. Avec ses nombreux stands et commerçants, chacun pourra trouver de nouvelles saveurs. Venez découvrir ce marché convivial pour un moment gourmand."},"site":"https://www.paris.fr/marches","adresse":"Entre le 14 place Lachambeaudie et le 11 rue Baron le Roy, 75012 Paris","majSource":"2026-09-01"},{"id":"dt-c0a8d3b1-4a74-3af5-a22d-b7afab098b88","cat":"marches","ville":"saint-mande","nom":"Marché aux Vieux Papiers de Saint-Mandé","lat":48.846375,"lon":2.416714,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/c0a8d3b1-4a74-3af5-a22d-b7afab098b88"}],"recupere":"2026-11-14","long":{"fr":"Découvrez un marché aux trésors, dédié aux cartes postales, timbres rares, documents d'époque et livres anciens. Rendez-vous chaque mercredi, de 9h à 18h, pour une immersion dans l'histoire à travers des objets uniques et chargés de souvenirs. Un rendez-vous incontournable pour les collectionneurs et les amateurs de belles trouvailles !"},"site":"https://tourisme-vincennes-marnebois.fr/fr/fetes-et-manifestations/marche-aux-vieux-papiers","adresse":"Avenue de Paris, 94160 Saint-Mandé","majSource":"2026-09-01"},{"id":"dt-e5124d2d-7fd2-3017-b77a-195f44d6e51c","cat":"shopping","ville":"saint-mande","nom":"Brasserie La Baleine","lat":48.852158,"lon":2.411281,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/e5124d2d-7fd2-3017-b77a-195f44d6e51c"}],"recupere":"2026-11-14","long":{"fr":"La Brasserie La Baleine, spécialisée dans la fabrication de bières blanches, blondes et ambrées, propose des recettes savoureuses et originales. Ouverte à la vente en directe, elle fournit aussi bien les particuliers que les professionnels et les associations. Découvrez des bières artisanales de qualité et soutenez une entreprise locale passionnée par son savoir-faire brassicole."},"site":"http://www.brasserielabaleine.com/","adresse":"17 rue Henri Duvernois, 75020 Paris","majSource":"2026-09-01"},{"id":"dt-4097b4d5-440f-38ec-8fe8-32366bfb82d8","cat":"restaurants","ville":"saint-mande","nom":"Il Goto","lat":48.840984,"lon":2.387432,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/4097b4d5-440f-38ec-8fe8-32366bfb82d8"}],"recupere":"2026-11-14","long":{"fr":"Plongez dans l'ambiance chaleureuse de l'It Goto, une trattoria italienne nichée au cœur du 12e arrondissement de Paris. Dirigé par un couple d'Italiens amoureux de gastronomie, ce petit bijou propose une carte ensoleillée où se mêlent antipasti, carpaccios, gnocchis et bien d'autres délices transalpins. Le tout dans un cadre sobre, mais convivial, où les saveurs italiennes sont à l'honneur à des prix tout doux. Une escapade gourmande à ne pas manquer!"},"site":"http://www.ilgoto.fr/","adresse":"212 bis rue de Charenton, 75012 Paris","majSource":"2026-09-01"},{"id":"dt-46de42ce-c427-3caa-a1ec-664b27889fd6","cat":"loisirs","ville":"saint-mande","nom":"Piscine Jean Boiteux","lat":48.842087,"lon":2.389364,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/46de42ce-c427-3caa-a1ec-664b27889fd6"}],"recupere":"2026-11-14","long":{"fr":"Nichée entre la Coulée verte René-Dumont et le quartier de Bercy, la piscine Jean Boiteux offre aux nageurs deux bassins : un de 25 mètres et un de 14 mètres. Les amateurs d'activités aquatiques y trouveront leur bonheur grâce à un large panel d'activités : aquagym, bébés nageurs, hockey subaquatique, plongée... Une véritable oasis aquatique au cœur de la capitale pour se détendre et se dépenser en toute sérénité."},"site":"https://www.paris.fr/","adresse":"13 rue Hénard, 75012 Paris","majSource":"2026-09-01"},{"id":"dt-862544c2-62e5-32bd-907a-4b7328ddda97","cat":"parcs","ville":"saint-mande","nom":"Jardin de Reuilly - Paul Pernin","lat":48.84221,"lon":2.387698,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/862544c2-62e5-32bd-907a-4b7328ddda97"}],"recupere":"2026-11-14","long":{"fr":"Le Jardin de Reuilly - Paul Pernin, le long de la Coulée Verte René Dumont, est un joyau vert. Ce jardin de 4 200 m² en pente douce, bordé de jardins à thème et de statues féminines, remplace une ancienne gare de marchandises. Conçu entre 1992 et 1998 par Pierre Colboc et Paysage, il offre une fontaine publique unique en France, proposant de l'eau fraîche ou gazeuse gratuitement. Une oasis de détente en ville."},"site":"https://www.paris.fr/lieux/jardin-de-reuilly-paul-pernin-2573","adresse":"15 rue Albinoni, 75012 Paris","majSource":"2026-09-01"},{"id":"dt-993d4e18-a74a-3d00-8984-3b5708c90b93","cat":"shopping","ville":"saint-mande","nom":"La Maison du Zéro Déchet","lat":48.848457,"lon":2.38576,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/993d4e18-a74a-3d00-8984-3b5708c90b93"}],"recupere":"2026-11-14","long":{"fr":"La Maison du Zéro Déchet lancée par Zero Waste France en 2017 est un espace convivial engagé pour le zéro déchet. Avec une boutique proposant des alternatives, une bibliothèque gratuite et un café associatif, elle encourage l'action. Son programme complet inclut conférences, tables rondes, projections-débats, ateliers pratiques et formations pour accompagner tous vers un mode de vie respectueux de l'environnement."},"site":"https://lamaisonduzerodechet.org/","adresse":"1 passage Emma Calvé, 75012 Paris","majSource":"2026-09-01"},{"id":"dt-db055d1c-8d46-35d1-88d1-93e227d47a08","cat":"loisirs","ville":"saint-mande","nom":"CRESCO","lat":48.844405,"lon":2.424283,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Etablissement Public territorial Paris Est Marne et Bois","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/db055d1c-8d46-35d1-88d1-93e227d47a08"}],"recupere":"2026-11-14","long":{"fr":"Cresco est le centre culturel et théâtre de la Ville de Saint-Mandé. Il promeut la culture sous toutes ses formes. Vous pouvez vous y rendre pour assister à un spectacle, suivre une activité associative mais aussi profiter d’un espace de travail."},"site":"https://www.saintmande.fr/pratique/culture-et-loisirs/cresco","adresse":"4 avenue Pasteur, 94165 Saint-Mandé","majSource":"2026-01-21"},{"id":"dt-4c818d1a-443b-3235-9740-3cd03c15e453","cat":"restaurants","ville":"saint-mande","nom":"Au Trou Gascon","lat":48.83912,"lon":2.394284,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/4c818d1a-443b-3235-9740-3cd03c15e453"}],"recupere":"2026-11-14","long":{"fr":"Laissez-vous séduire par ce restaurant gastronomique à l'ambiance raffinée, où les saveurs du Sud-Ouest et les plats de gibier sont à l'honneur. Vous apprécierez également la sélection généreuse de vins qui accompagnera parfaitement votre repas. Une adresse incontournable pour les amateurs de bonne cuisine et de dégustation raffinée."},"site":"http://www.alaindutournier.com/wp/autrougascon","adresse":"40 rue Taine, 75012 Paris","majSource":"2026-09-01"},{"id":"dt-8cf78e27-b7c0-34b2-b53a-9aeaa99befa6","cat":"shopping","ville":"saint-mande","nom":"YC Workshop","lat":48.848252,"lon":2.420363,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Etablissement Public territorial Paris Est Marne et Bois","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/8cf78e27-b7c0-34b2-b53a-9aeaa99befa6"}],"recupere":"2026-11-14","long":{"fr":"Yin Chang est artisane d’art céramiste, fondatrice de son atelier à Vincennes. Elle y conçoit et fabrique des pièces utilitaires et contemporaines, réalisées à la main, à la croisée du geste artisanal, de la création, et de la recherche sur les matériaux."},"site":"https://ycworkshop.fr/","adresse":"53 rue Massue, 94300 Vincennes","majSource":"2026-02-19"},{"id":"dt-dd1d481c-1ab0-30ae-a32d-8352be91ccd2","cat":"restaurants","ville":"saint-mande","nom":"Artishow Cabaret","lat":48.851585,"lon":2.388957,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/dd1d481c-1ab0-30ae-a32d-8352be91ccd2"}],"recupere":"2026-11-14","long":{"fr":"Venez vivre un incroyable spectacle au cabaret de l'Artishow ! Transformisme, chant, danse, tout y est pour vous offrir une soirée haute en couleurs. Profitez d'un éclairage technologique dernier cri. Réservez une formule dîner-spectacle ou déjeuner-spectacle pour une expérience complète. Célébrez un anniversaire ou un événement dans une ambiance festive et conviviale."},"site":"https://www.artishowcabaret.com/","adresse":"3 cité Souzy, 75011 Paris","majSource":"2026-09-01"},{"id":"dt-bac5b815-a7e0-3cdc-af76-0ef8e0dae747","cat":"patrimoine","ville":"saint-mande","nom":"Eglise Notre-Dame","lat":48.839528,"lon":2.417468,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Etablissement Public territorial Paris Est Marne et Bois","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/bac5b815-a7e0-3cdc-af76-0ef8e0dae747"}],"recupere":"2026-11-14","long":{"fr":"Construite de 1883 à 1885 par l'architecte Edmond-Charles d'Albrizio en remplacement de l'ancienne chapelle du XVIIIe siècle, devenue insuffisante pour faire face au développement de la ville."},"site":"https://paroisses-ndsm-slv.fr/","adresse":"84 avenue du Général de Gaulle, 94160 Saint-Mandé","majSource":"2026-06-25"},{"id":"dt-fb59ddf9-be24-3cbb-a9a9-e8f2999d8d8a","cat":"patrimoine","ville":"saint-mande","nom":"Palais de la Porte Dorée","lat":48.834913,"lon":2.409135,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Etablissement Public territorial Paris Est Marne et Bois","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/fb59ddf9-be24-3cbb-a9a9-e8f2999d8d8a"}],"recupere":"2026-11-14","long":{"fr":"Chef-d’œuvre de l'Art déco parisien, le Palais de la Porte Dorée impressionne par son architecture monumentale, ses décors sculptés et ses fresques remarquables. Une visite incontournable pour découvrir l'un des plus beaux monuments des années 1930."},"site":"http://www.palais-portedoree.fr/","adresse":"293 avenue Daumesnil, 75012 Paris","majSource":"2026-08-06"},{"id":"dt-0192caa6-1b5a-348b-9f68-02e83df098d6","cat":"patrimoine","ville":"saint-mande","nom":"Église Saint-Éloi","lat":48.84486,"lon":2.389116,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/0192caa6-1b5a-348b-9f68-02e83df098d6"}],"recupere":"2026-11-14","long":{"fr":"L'église Saint-Éloi, conçue par l'architecte Marc Leboucher, se trouve entre la place de la Nation et la gare de Lyon. Elle se distingue par sa structure en charpente métallique revêtue d'aluminium à l'intérieur et à l'extérieur. Une imposante tour métallique abrite les cloches, ajoutant une touche moderne à cet édifice religieux."},"site":"http://www.steloi.com/","adresse":"3 place Maurice de Fontenay, 75012 Paris","majSource":"2026-09-01"},{"id":"dt-80093a12-867d-3c0e-92e4-4a8625cf9f45","cat":"restaurants","ville":"saint-mande","nom":"Fulgurances - L'Adresse","lat":48.852949,"lon":2.389889,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/80093a12-867d-3c0e-92e4-4a8625cf9f45"}],"recupere":"2026-11-14","long":{"fr":"Découvrez à L'Adresse un lieu exceptionnel pour les amateurs de gastronomie en quête de nouvelles sensations. Le Fulgurances - L'Adresse accueille de jeunes chefs en résidence pendant 6 mois, offrant ainsi une opportunité unique d'explorer leur créativité et de perfectionner leur art. Ne manquez pas cette adresse pour un voyage gustatif prometteur."},"site":"https://fulgurances.com/les-restaurants/ladresse-paris/","adresse":"10 rue Alexandre Dumas, 75011 Paris","majSource":"2026-09-01"},{"id":"dt-d8e62bc5-3ecb-3da0-8fa2-68418a8acb70","cat":"parcs","ville":"saint-mande","nom":"Coulée verte René-Dumont depuis Saint-Mandé","lat":48.839811,"lon":2.413748,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Choose Paris Region","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/d8e62bc5-3ecb-3da0-8fa2-68418a8acb70"}],"recupere":"2026-11-14","long":{"fr":"Pour une balade pittoresque et insolite dans le 12ème arrondissement, découvrez la Coulée verte René Dumont."},"site":"http://equipement.paris.fr/coulee-verte-rene-dumont-ex-promenade-plantee-1772","adresse":"21 avenue Emile Laurent, 75012 Paris","majSource":"2025-11-25"},{"id":"dt-4214e1a6-dffe-3353-9c50-7c25b7543e8d","cat":"cafes","ville":"saint-mande","nom":"Bonjour Madame","lat":48.850389,"lon":2.387194,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/4214e1a6-dffe-3353-9c50-7c25b7543e8d"}],"recupere":"2026-11-14","long":{"fr":"Bonjour Madame est un bar culturel et féministe queer dans le 11e arrondissement de Paris. On y prend un verre et on profite d'un espace social et d'une programmation d’événements incluant concerts, expositions et discussions dans un cadre inclusif et convivial."},"site":"https://www.instagram.com/bonjourmadame_paris/","adresse":"40 rue de Montreuil, 75011 Paris","majSource":"2026-09-01"},{"id":"dt-7f017175-f202-3666-9345-cd758b5f5b98","cat":"musees","ville":"saint-mande","nom":"La Cinémathèque française","lat":48.837188,"lon":2.382724,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Choose Paris Region","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/7f017175-f202-3666-9345-cd758b5f5b98"}],"recupere":"2026-11-14","long":{"fr":"La Cinémathèque réunit dans un édifice signé F.O. Gehry l’une des plus importantes collections de cinéma au monde."},"site":"http://www.cinematheque.fr/","adresse":"51 Rue de Bercy, 75012 Paris","majSource":"2026-06-24"},{"id":"dt-6a11d61e-1490-3214-97e1-445fbb62e01a","cat":"cafes","ville":"saint-mande","nom":"Bar rooftop Jo&joe","lat":48.85127,"lon":2.399555,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/6a11d61e-1490-3214-97e1-445fbb62e01a"}],"recupere":"2026-11-14","site":"https://www.joandjoe.com/paris-nation/fr/restaurant-and-bar/","adresse":"59-61 rue de Buzenval, 75020 Paris","majSource":"2026-09-01"},{"id":"dt-9da8fd14-726f-38df-90b3-a5926e828b23","cat":"restaurants","ville":"saint-mande","nom":"Restaurant Jo&Joe","lat":48.85127,"lon":2.399555,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/9da8fd14-726f-38df-90b3-a5926e828b23"}],"recupere":"2026-11-14","site":"https://www.joandjoe.com/paris-gentilly/fr/restaurant-and-bar/","adresse":"59-61 rue de Buzenval, 75020 Paris","majSource":"2026-09-01"},{"id":"dt-9ea0fe6a-c45f-31dd-8cde-c62a904ec9d2","cat":"patrimoine","ville":"saint-mande","nom":"Colonne du cimetière Nord de Saint-Mandé","lat":48.848525,"lon":2.418344,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Etablissement Public territorial Paris Est Marne et Bois","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/9ea0fe6a-c45f-31dd-8cde-c62a904ec9d2"}],"recupere":"2026-11-14","long":{"fr":"Érigée dès l'ouverture du cimetière en 1825, cette colonne est l'un des plus anciens vestiges du site. Aujourd'hui située sur la droite du passage, elle se dressait à l'origine au centre de la nécropole, marquant l'intersection des allées principales."},"adresse":"24 avenue Joffre, 94160 Saint-Mandé","majSource":"2026-04-23"}]);
